package main

import (
	"io"
	"os"
)

// ❌ OLD: Manual cleanup. If a future edit adds another error return
// before f.Close(), the file leaks (fd exhaustion). Manually closing
// on every path is repetitive and error-prone.
func read(path string) ([]byte, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	data, err := io.ReadAll(f)
	f.Close() // ❌ OLD: only reached if ReadAll returns
	return data, err
}

// A panic or an added early return skips Close entirely.

