package main

import (
	"io"
	"os"
)

// ✅ NEW: defer guarantees f.Close() runs on EVERY exit path (normal
// return, error return, panic). In Go 1.14+, this simple case is
// OPEN-CODED: the compiler inlines the close into the function's
// return epilogue with a deferBits mask — no heap allocation, no
// _defer record, essentially zero overhead.
func read(path string) ([]byte, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close() // ✅ NEW: free in the common case
	return io.ReadAll(f)
}

// Defers run LIFO and arguments are evaluated at defer time:
// defer fmt.Println(x) captures x's value NOW, not at return.
